"""Generated by the NL to Flow Diagram Encoder Pipeline."""

import random as _aj_random

import random

print('Auto Maze Generator and BFS Solver\n')

def shuffle_dirs(dirs):
    for i in range(0, len(dirs)):
        j = _aj_random.randint(0, (len(dirs) - 1))
        swap_values = (dirs[j], dirs[i])
        dirs[i] = swap_values[0]
        dirs[j] = swap_values[1]

def carve_maze(maze, rows, cols):
    stack = []
    r = 1
    c = 1
    maze[r][c] = ' '
    stack.append((r, c))
    while (len(stack) > 0):
        position = stack[(-1)]
        r = position[0]
        c = position[1]
        dirs = [(0, 2), (0, (-2)), (2, 0), ((-2), 0)]
        shuffle_dirs(dirs)
        carved = False
        for direction in dirs:
            dr = direction[0]
            dc = direction[1]
            nr = (r + dr)
            nc = (c + dc)
            if (((1 <= nr) and (nr < (rows - 1))) and ((1 <= nc) and (nc < (cols - 1)))):
                if (maze[nr][nc] == '▓'):
                    maze[(r + (dr // 2))][(c + (dc // 2))] = ' '
                    maze[nr][nc] = ' '
                    stack.append((nr, nc))
                    carved = True
                    break
        if (not carved):
            stack.pop()

def solve_maze_bfs(maze, rows, cols):
    start = None
    end = None
    for r in range(0, rows):
        for c in range(0, cols):
            if (maze[r][c] == 'S'):
                start = (r, c)
            elif (maze[r][c] == 'E'):
                end = (r, c)
    queue = [start]
    visited = {}
    visited[start] = None
    i = 0
    while (i < len(queue)):
        queue_position = queue[i]
        r = queue_position[0]
        c = queue_position[1]
        if ((r, c) == end):
            break
        for direction in [(1, 0), ((-1), 0), (0, 1), (0, (-1))]:
            dr = direction[0]
            dc = direction[1]
            nr = (r + dr)
            nc = (c + dc)
            if ((((0 <= nr) and (nr < rows)) and (0 <= nc)) and (nc < cols)):
                if ((maze[nr][nc] != '▓') and ((nr, nc) not in visited)):
                    visited[(nr, nc)] = (r, c)
                    queue.append((nr, nc))
        i = (i + 1)
    path = []
    node = end
    while (node is not None):
        path.insert(0, node)
        node = visited[node]
    return path

def mark_path(maze, path):
    for path_cell in path:
        r = path_cell[0]
        c = path_cell[1]
        if (maze[r][c] not in ('S', 'E')):
            maze[r][c] = '•'

def display_maze(maze):
    for row in maze:
        print(''.join(row))

def create_grid(rows, cols):
    if ((rows % 2) == 1):
        carve_rows = rows
    else:
        carve_rows = (rows - 1)
    if ((cols % 2) == 1):
        carve_cols = cols
    else:
        carve_cols = (cols - 1)
    maze = []
    for _ in range(0, rows):
        maze_row = []
        for _ in range(0, cols):
            maze_row.append('▓')
        maze.append(maze_row)
    carve = []
    for _ in range(0, carve_rows):
        carve_row = []
        for _ in range(0, carve_cols):
            carve_row.append('▓')
        carve.append(carve_row)
    carve_maze(carve, carve_rows, carve_cols)
    for r in range(0, carve_rows):
        for c in range(0, carve_cols):
            maze[r][c] = carve[r][c]
    maze[1][1] = 'S'
    maze[(carve_rows - 2)][(carve_cols - 2)] = 'E'
    path = solve_maze_bfs(maze, rows, cols)
    mark_path(maze, path)
    display_maze(maze)
    return maze

create_grid(11, 20)
